-- The exercise catalogue: 1,283 distinct movements from ExerciseDB with their
-- animations (served from static.exercisedb.dev by id; entries whose animation
-- 404s were swapped for a working duplicate). Staples carry a rank so search
-- and the picker lead with the lifts people actually do.

on conflict (id) do update set name = excluded.name, body_part = excluded.body_part, target = excluded.target,
  secondary = excluded.secondary, equipment = excluded.equipment, steps = excluded.steps, rank = excluded.rank;
