insert into public.exercises (id, name, body_part, target, secondary, equipment, steps, rank) values
('01qpYSe','Upward Facing Dog','back','erector spinae',array['deltoids','pectorals'],'bodyweight',array['Position yourself face down on the floor with your legs extended behind you.','Set your hands on the floor next to your lower ribs, fingers pointing forward.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('03lzqwk','Assisted Hanging Knee Raise','waist','abdominals',array['hip flexors'],'assisted',array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.','Brace your trunk muscles and lift your knees toward your chest, bending at the hips and knees.','Brace the abdomen and keep the shoulders anchored to the support.','Lift your legs by bracing your trunk and moving at the hips rather than swinging.','Slow the legs before they pull the lower back out of position.','Lower the legs slowly without swinging or losing your trunk position.'],0),
('05Cf2v8','Impossible Dips','upper arms','triceps',array['pectorals','deltoids'],'bodyweight',array['Set yourself between two parallel bars with your arms straight and your body suspended in the air.','Before moving, bend your knees and cross your ankles.','Set the shoulders down and keep the elbows pointed mostly behind you.','Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.','Choose a depth that lets the shoulders stay comfortable.','Press through the hands to rise, then reset the shoulders before another rep.'],0),
('0br45wL','Push-Up Inside Leg Kick','upper legs','glutes',array['quadriceps','hamstrings','calves','core'],'bodyweight',array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.','Lower your body toward the ground by bending your elbows, with your spine steady and your core engaged.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('0CXGHya','Cable Crossover','chest','pectorals',array['deltoids','triceps'],'cable',array['Set the cable pulleys to chest height.','Take your place in the center of the cable machine with one foot in front of the other.','Keep a soft elbow bend and set the shoulders before moving the arms.','Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.','Keep the elbow angle nearly unchanged through the arc.','Open the arms back along the same arc without dropping the load.'],24),
('0dCyly0','Barbell Seated Bradford Rocky Press','shoulders','deltoids',array['triceps','upper back'],'barbell',array['Take a seat on a bench with your back straight and feet planted.','Take hold of the barbell with palms facing down, just beyond shoulder width.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('0IgNjSM','Dumbbell Standing Reverse Curl','upper arms','biceps',array['forearms'],'dumbbell',array['Stand tall with your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.','With your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.','Set the shoulders and upper arms before bending the elbows.','Curl the weight with your palms facing down, keeping the elbows close and torso still.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('0jp9Rlz','Single-Leg Floor Calf Raise','lower legs','calves',array['ankles','feet'],'bodyweight',array['Stand and set your feet about hip width and place your hands on a wall or sturdy object for balance.','Before moving, lift one foot off the ground and balance on the other foot.','Let the ankles move freely while the rest of the body stays quiet.','Rise through the balls of your feet, lifting the heels as high as you can without rocking.','Keep the pelvis level as the supporting leg does the work.','Lower the heels at a measured pace before rising again; switch sides when the set calls for it.'],0),
('0JtKWum','Dumbbell Burpee','cardio','cardiovascular system',array['quadriceps','hamstrings','calves','deltoids','triceps','core'],'dumbbell',array['Begin in a standing position with your feet about shoulder width and a dumbbell in each hand.','Before moving, lower your body into a squat position, placing the dumbbells on the ground in front of you.','Start at a pace that lets the feet and arms move in sync.','Move at a repeatable pace, keeping the motion smooth and your breathing steady.','Keep the pattern repeatable as speed increases.','Keep the rhythm for the planned interval, slowing if your form starts to slip.'],0),
('0L2KwtI','Roller Hip Lat Stretch','upper legs','glutes',array['hamstrings','quadriceps'],'roller',array['Begin by kneeling on the ground with the roller positioned under your hips.','Set your hands on the roller for support.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('0lQnxMZ','Weighted Sissy Squat','upper legs','quadriceps',array['glutes','hamstrings','calves'],'weighted',array['Stand and set your feet about shoulder width and your toes pointing slightly outward.','Take a weight ahead of your chest with both hands, or place a barbell across your upper back.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('0mB6wHO','Runners Stretch','upper legs','hamstrings',array['calves','quadriceps'],'bodyweight',array['Stand and set your feet about hip width.','Step forward with your right foot, keeping your left foot planted.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('0rHfvy9','Inverse Leg Curl (On Pull-Up Cable Machine)','upper legs','hamstrings',array['glutes','calves'],'bodyweight',array['Set the cable machine so that the ankle straps are at the lowest setting.','Position yourself face down on the bench with your legs extended and the ankle straps attached to your feet.','Line the knees up with the machine or bench edge before starting the curl.','Bend your knees to draw the pad toward you without lifting your hips from the support.','Keep the hips still while the knees bend.','Ease back to the start before repeating.'],0),
('0S75mYG','Smith Seated Single-Leg Calf Raise','lower legs','calves',array['hamstrings'],'smith machine',array['Take a seat on the machine with your back against the pad and your feet on the footrest.','Set one leg on the footrest and keep the other leg off the footrest.','Let the ankles move freely while the rest of the body stays quiet.','Rise through the balls of your feet, lifting the heels as high as you can without rocking.','Keep the pelvis level as the supporting leg does the work.','Lower the heels at a measured pace before rising again; switch sides when the set calls for it.'],0),
('0V2YQjW','Pull-Up (Neutral Grip)','back','latissimus dorsi',array['biceps','forearms'],'bodyweight',array['Suspend yourself from a pull-up bar with a neutral grip (palms facing each other) and your arms straight.','Brace your trunk and draw your shoulder blades toward each other.','Begin from a controlled hang with the shoulders active rather than slack.','Pull your elbows down and bring your upper chest toward the bar without kicking your legs.','Avoid swinging the legs to clear the bar.','Lower to long arms without dropping suddenly from the top.'],0),
('0xDpB4L','Band Seated Hip Abduction','upper legs','abductors',array['glutes','hamstrings'],'resistance band',array['Take a seat on a chair or bench with your back straight and feet planted.','Loop the resistance band around your thighs, just above your knees.','Square the pelvis before moving the working leg.','Open the knees or legs against resistance without shifting your torso.','Control the band on the way back instead of letting it snap you into position.','Return along the same path at a controlled pace.'],0),
('0Yz8WdV','Bear Crawl','cardio','cardiovascular system',array['core','deltoids','triceps'],'bodyweight',array['Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.','Before moving, lift your knees slightly off the ground, keeping your back flat and your core engaged.','Start at a pace that lets the feet and arms move in sync.','Move at a repeatable pace, keeping the motion smooth and your breathing steady.','Keep the pattern repeatable as speed increases.','Keep the rhythm for the planned interval, slowing if your form starts to slip.'],0),
('10Z2DXU','Sled 45° Leg Press','upper legs','glutes',array['quadriceps','hamstrings','calves'],'sled machine',array['Set the seat and footplate of the sled machine to a comfortable position.','Take a seat on the sled machine with your back against the backrest and your feet about shoulder width on the footplate.','Set your feet firmly on the plate and keep the hips against the seat.','Bend the knees to bring the platform toward you, then press it away through the feet.','Stop the descent before the hips lift from the seat.','Bring the weight or body back to its starting position without rushing.'],33),
('11wrviz','Isometric Wipers','chest','pectorals',array['deltoids','triceps','core'],'bodyweight',array['Begin by lying flat on your back on a mat or bench.','Reach your arms straight out to the sides, perpendicular to your body.','Set the pelvis and make the turn through the rib cage.','Keep the trunk braced as the legs move together from side to side.','Keep the turn smooth instead of throwing the arms across the body.','Return through center before turning to the other side.'],0),
('13TpY4H','Raise Single Arm Push-Up','chest','pectorals',array['triceps','deltoids','core'],'bodyweight',array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.','Reach one arm straight out to the side, parallel to the ground.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('13VW2VO','Weighted Stretch Lunge','upper legs','glutes',array['quadriceps','hamstrings','calves'],'weighted',array['Stand and set your feet about shoulder width.','Step forward with your right foot, with your spine steady.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('17bqEXD','Seated Calf Stretch','lower legs','calves',array['hamstrings'],'bodyweight',array['Take a seat on the edge of a chair or bench with your feet planted.','Reach one leg straight out in front of you, keeping your heel on the ground.','Settle into the starting position and take an easy breath before moving deeper.','Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('17lJ1kr','Machine Lying Leg Curl','upper legs','hamstrings',array['calves'],'leverage machine',array['Set the machine to fit your body and select the desired weight.','Position yourself face down on the machine with your legs straight and your heels against the padded lever.','Line the knees up with the machine or bench edge before starting the curl.','Bend your knees to draw the pad toward you without lifting your hips from the support.','Keep the hips still while the knees bend.','Ease back to the start before repeating.'],35),
('196HJGw','Hip Raise (Bent Knee)','waist','abdominals',array['glutes','hamstrings'],'bodyweight',array['Settle onto your back with your knees bent and feet planted.','Set your hands by your sides, palms facing down.','Plant the feet and keep the ribs from flaring as the hips prepare to rise.','Press through the feet and lift your hips until your torso and thighs line up.','Stop when the hips line up with the torso; do not arch higher through the lower back.','Lower the hips steadily and keep the feet planted for the next lift.'],0),
('1bQkKZK','Smith Bent Knee Good Morning','upper legs','glutes',array['hamstrings','erector spinae'],'smith machine',array['Begin by standing with your feet about shoulder width, toes pointing forward.','Set the barbell across your upper back, resting it on your traps.','Unlock the knees and brace the abdomen before moving the hips back.','Push the hips back while keeping the load close and the spine steady.','Keep the weight close to the legs and stop when the back would begin to round.','Drive the hips forward to stand tall without leaning back at the top.'],0),
('1cTf2Ux','Ez-Bar Standing French Press','upper arms','triceps',array['deltoids'],'EZ bar',array['Stand and set your feet about shoulder width and hold the ez barbell with palms facing down.','Raise the barbell above your head, straighten your arms.','Set the upper arms in place before extending the elbows.','Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.','Keep the upper arms steady while the forearms travel.','Straighten the elbows to bring the bar overhead, then begin the next controlled rep.'],0),
('1DN3iz4','Smith Upright Row','shoulders','deltoids',array['trapezius','biceps'],'smith machine',array['Stand and set your feet about shoulder width, facing the smith machine.','Hold the barbell with palms facing down, hands just beyond shoulder width.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('1g5bPpA','Jack Jump','cardio','cardiovascular system',array['quadriceps','calves'],'bodyweight',array['Stand and set your feet together and your arms by your sides.','Before moving, jump up, spreading your feet apart and raising your arms above your head.','Bend the hips and knees slightly to load the jump.','Load the legs with a small bend, then drive through the floor and land softly.','Land with bent hips and knees and let the feet absorb the impact.','Absorb the landing through the hips and knees before repeating.'],0),
('1gFNTZV','Barbell Jump Squat','upper legs','glutes',array['quadriceps','hamstrings','calves'],'barbell',array['Begin by standing with your feet about shoulder width, holding a barbell across your upper back.','Before moving, lower your body into a squat position by bending your knees and pushing your hips back.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('1GPHRyK','Janda Sit-Up','waist','abdominals',array['hip flexors','erector spinae'],'bodyweight',array['Settle onto your back with your knees bent and feet planted.','Set your hands behind your head with your elbows pointing outwards.','Set the pelvis and keep the neck relaxed before curling upward.','Curl your rib cage toward your pelvis, letting the abdominals move the torso.','Leave a little space between the chin and chest; keep the movement in the torso.','Lower the shoulders or torso with control before the next curl.'],0),
('1IG6gVF','Prone Twist on Stability Ball','waist','abdominals',array['obliques','erector spinae'],'stability ball',array['Begin by lying face down on a stability ball with your feet about shoulder width and your toes touching the ground.','Set your hands behind your head or cross them over your chest.','Set the pelvis and make the turn through the rib cage.','Turn through the torso while the hips and lower body stay as steady as the setup allows.','Keep the ball steady and use the feet to manage your balance.','Return through center before turning to the other side.'],0),
('1jXLYEw','Standing Lateral Stretch','back','latissimus dorsi',array['deltoids','obliques'],'bodyweight',array['Stand and set your feet about shoulder width and your knees soft.','Reach your arms straight out to the sides, parallel to the ground.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('1kB3Wmk','Dumbbell Single Leg Calf Raise','lower legs','calves',array['ankles'],'dumbbell',array['Step onto the edge of a step or platform with your heels hanging off and your toes on the step.','Take a dumbbell in one hand and place your other hand on a wall or railing for support.','Let the ankles move freely while the rest of the body stays quiet.','Rise through the balls of your feet, lifting the heels as high as you can without rocking.','Pause at the top without rolling the ankles outward.','Lower the heels at a measured pace before rising again.'],0),
('1LVFcEn','Calf Stretch with Rope','lower legs','calves',array['hamstrings'],'rope',array['Face a wall or sturdy object with your feet about hip width.','Take hold of the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.','Settle into the starting position and take an easy breath before moving deeper.','Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('1PK5Uo3','Cable Incline Pushdown','back','latissimus dorsi',array['triceps','deltoids'],'cable',array['Connect a straight bar to a high pulley cable machine.','Face the away from the machine from a stable stance with feet about shoulder width.','Stand far enough from the stack for the cable to stay taut.','Keep your elbows near your ribs and straighten your arms against the cable.','Keep the elbows close to the body instead of letting the shoulders swing.','Return along the same path at a controlled pace.'],0),
('1PLE8e9','Dumbbell Incline Twisted Flyes','chest','pectorals',array['deltoids','triceps'],'dumbbell',array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.','Recline on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.','Keep a soft elbow bend and set the shoulders before moving the arms.','With a soft bend in the elbows, sweep your arms together in a wide arc.','Keep the elbow angle nearly unchanged through the arc.','Open the arms back along the same arc without dropping the load.'],0),
('1qrWgZ2','Dumbbell Decline Hammer Press','chest','pectorals',array['triceps','deltoids'],'dumbbell',array['Secure the feet on a decline bench, keeping the head below the hips.','Take a dumbbell in each hand with your palms facing each other and your arms extended above your chest.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the palms facing each other and the wrists straight.','Lower the weight to its starting height under control before pressing again.'],0),
('1TkiAFK','Dumbbell Single-Arm Shoulder Press','shoulders','deltoids',array['triceps','upper back'],'dumbbell',array['Stand and set your feet about shoulder width and hold a dumbbell in one hand at shoulder level, palm facing forward.','Brace your trunk and press the dumbbell straight up overhead, fully extending your arm.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep both shoulders level and resist turning toward the working arm.','Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.'],0),
('1V1gj1u','Barbell Seated Close-Grip Concentration Curl','upper arms','biceps',array['forearms'],'barbell',array['Plant both feet while seated on a bench; hold a barbell with palms facing up, hands about shoulder width.','Set your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('1VpF8db','Dumbbell Biceps Curl Lunge with Bowling Motion','upper arms','biceps',array['forearms','deltoids'],'dumbbell',array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing forward.','Step forward with your right foot, bending your right knee and lowering your body into a lunge position.','Set your stance wide enough to balance before bending either knee.','Step into the movement and bend both knees, keeping your front foot planted.','Keep the front foot planted and avoid collapsing inward at the knee.','Push through the lead foot to return to the start, then change legs as planned.'],0),
('1xHyxys','Cable High Pulley Overhead Triceps Extension','upper arms','triceps',array['deltoids'],'cable',array['Connect a rope to a high pulley and stand turned away from the machine.','Hold the rope with both hands and extend your arms overhead.','Set the upper arms in place before extending the elbows.','Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('1YB40kg','Incline Close-Grip Push-Up','upper arms','triceps',array['pectorals','deltoids'],'bodyweight',array['Set your hands close together on a stable raised surface, then walk the feet back into a plank.','Reach your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('1ZFqTDN','Bicycle Crunch','waist','abdominals',array['hip flexors'],'bodyweight',array['Settle onto your back with your hands placed behind your head.','Before moving, lift your legs off the ground and bend your knees at a 90-degree angle.','Set the pelvis and keep the neck relaxed before curling upward.','Bring one elbow toward the opposite knee as the other leg extends; switch sides in a steady rhythm.','Leave a little space between the chin and chest; keep the movement in the torso.','Lower the shoulders or torso with control before the next curl.'],0),
('225x2Vd','Band Kneeling Twisting Crunch','waist','abdominals',array['obliques'],'resistance band',array['Connect the band to a sturdy anchor point at waist height.','Kneel turned away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.','Set the pelvis and keep the neck relaxed before curling upward.','Curl your rib cage toward your pelvis, letting the abdominals move the torso.','Control the band on the way back instead of letting it snap you into position.','Lower the shoulders or torso with control before the next curl.'],0),
('25GPyDY','Barbell Curl','upper arms','biceps',array['forearms'],'barbell',array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up, palms facing forward.','Hold your elbows near your torso and Breathe out and curl the weights while contracting your biceps.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],29),
('27NNGFr','Cable Incline Fly (On Stability Ball)','chest','pectorals',array['deltoids','triceps'],'cable',array['Prepare a stability ball at an incline angle.','Connect the cable handles to the high pulleys of a cable machine.','Keep a soft elbow bend and set the shoulders before moving the arms.','With a soft bend in the elbows, sweep your arms together in a wide arc.','Keep the ball steady and use the feet to manage your balance.','Open the arms back along the same arc without dropping the load.'],0),
('2dImyQ8','Dumbbell Seated Palms Up Wrist Curl','lower arms','forearms',array['biceps','deltoids'],'dumbbell',array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.','Set your forearms on your thighs, letting your wrists hang off the edge.','Keep the elbows relaxed so the small muscles of the hand or forearm take the load.','Move through the wrists or fingers while the forearms stay supported and still.','Use a small, smooth range without swinging the elbows.','Ease back to the start without letting the load fall from your hands.'],0),
('2Dk4xQV','Rocking Frog Stretch','upper legs','glutes',array['hamstrings','quadriceps'],'bodyweight',array['Begin by kneeling on the ground with your knees about hip width.','Set your hands on the ground in front of you for support.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('2DxtqHL','Barbell Single-Arm Side Deadlift','upper legs','glutes',array['hamstrings','quadriceps','erector spinae'],'barbell',array['Stand and set your feet about shoulder width, holding a barbell in one hand with palms facing down.','Keep your spine in a comfortable neutral position and your core engaged.','Unlock the knees and brace the abdomen before moving the hips back.','Push the hips back while keeping the load close and the spine steady.','Keep both shoulders level and resist turning toward the working arm.','Drive the hips forward to stand tall without leaning back at the top; switch sides when the set calls for it.'],0),
('2gPfomN','3/4 Sit-Up','waist','abdominals',array['hip flexors','erector spinae'],'bodyweight',array['Settle onto your back with your knees bent and feet planted.','Set your hands behind your head with your elbows pointing outwards.','Set the pelvis and keep the neck relaxed before curling upward.','Curl your rib cage toward your pelvis, letting the abdominals move the torso.','Leave a little space between the chin and chest; keep the movement in the torso.','Lower the shoulders or torso with control before the next curl.'],0),
('2IHEa2T','Barbell Floor Calf Raise','lower legs','calves',array['hamstrings'],'barbell',array['Set a barbell on the floor in front of you.','Stand and set the balls of your feet on the edge of the barbell, with your heels hanging off.','Let the ankles move freely while the rest of the body stays quiet.','Rise through the balls of your feet, lifting the heels as high as you can without rocking.','Pause at the top without rolling the ankles outward.','Lower the heels at a measured pace before rising again.'],0),
('2IxROQ1','Cable Overhead Triceps Extension (Rope Attachment)','upper arms','triceps',array['deltoids'],'cable',array['Connect a rope to a cable machine at a high position.','Face the away from the machine from a stable stance with feet about shoulder width.','Set the upper arms in place before extending the elbows.','Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],11),
('2JCuFTU','Dumbbell Kneeling Biceps Curl Exercise Ball','upper arms','biceps',array['forearms'],'dumbbell',array['Get down on the floor with an exercise ball in front of you.','Set your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the ball steady and use the feet to manage your balance.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('2jl9K55','Spine Twist','waist','abdominals',array['obliques','erector spinae'],'bodyweight',array['Take a seat on the ground with your legs extended in front of you.','Bend your knees and place your feet planted, about hip width.','Set the pelvis and make the turn through the rib cage.','Turn through the torso while the hips and lower body stay as steady as the setup allows.','Keep the turn smooth instead of throwing the arms across the body.','Return through center before turning to the other side.'],0),
('2kattbR','Ez-Bar Spider Curl','upper arms','biceps',array['forearms'],'EZ bar',array['Stand and set your feet about shoulder width and hold the ez barbell with palms facing up.','Set your upper arms on a preacher bench or stability ball, letting your elbows to hang down.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('2KGnL6M','Machine Single-Arm Shoulder Press','shoulders','deltoids',array['triceps','upper back'],'leverage machine',array['Fit the seat to your body, then settle into the machine.','Hold the lever handle with one hand and position your elbow at a 90-degree angle.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep both shoulders level and resist turning toward the working arm.','Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.'],0),
('2kr2lWy','Push-Up (Bosu Ball)','chest','pectorals',array['triceps','deltoids','core'],'bosu ball',array['Set the bosu ball on the ground with the flat side facing up.','Set yourself in a push-up position with your hands on the outer edges of the bosu ball.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('2LQkNPW','Exercise Ball Hip Flexor Stretch','upper legs','glutes',array['quadriceps','hamstrings'],'stability ball',array['Set the stability ball on the ground and kneel in front of it.','Set your right foot on top of the stability ball, with your knee bent at a 90-degree angle.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Keep the ball steady and use the feet to manage your balance.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('2NImIAG','Dumbbell Biceps Curl on Exercise Ball with Leg Raised','upper arms','biceps',array['forearms','deltoids'],'dumbbell',array['Take a seat on an exercise ball with your feet planted and your back straight.','Take a dumbbell in each hand with your palms facing forward and your arms straight.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the ball steady and use the feet to manage your balance.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('2NpxjC1','Dumbbell Hammer Curl','upper arms','biceps',array['forearms'],'dumbbell',array['Stand tall with a dumbbell in each hand, palms facing your torso.','Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.','Set the shoulders and upper arms before bending the elbows.','Curl with palms facing each other and elbows near your sides; avoid rocking back.','Keep the palms facing each other and the wrists straight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],28),
('2ORFMoR','Hack Calf Raise','lower legs','calves',array['hamstrings','glutes'],'sled machine',array['Set the sled machine to a comfortable weight.','Step onto the sled machine with your toes on the platform and your heels hanging off.','Let the ankles move freely while the rest of the body stays quiet.','Rise through the balls of your feet, lifting the heels as high as you can without rocking.','Pause at the top without rolling the ankles outward.','Lower the heels at a measured pace before rising again.'],0),
('2Pya1cP','Cable Decline Press','chest','pectorals',array['triceps','deltoids'],'cable',array['Set the cable machine to a decline position.','Take a seat on the decline bench facing the cable machine.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('2qTvJAZ','Barbell Standing Back Wrist Curl','lower arms','forearms',array['biceps','deltoids'],'barbell',array['Stand tall with your feet about shoulder width and hold a barbell with palms facing down.','Rest the barbell on the back of your hands with your palms facing down and your fingers pointing toward your body.','Keep the elbows relaxed so the small muscles of the hand or forearm take the load.','Move through the wrists or fingers while the forearms stay supported and still.','Use a small, smooth range without swinging the elbows.','Ease back to the start without letting the load fall from your hands.'],0),
('2Ryn564','Assisted Prone Rectus Femoris Stretch','waist','abdominals',array['quadriceps'],'assisted',array['Position yourself face down on the ground with your legs straight.','Before moving, bend your right knee and reach back with your right hand to grab your right foot or ankle.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('2sQGZ5b','Dumbbell Single-Arm Standing Hammer Curl','upper arms','biceps',array['forearms'],'dumbbell',array['Stand tall with a dumbbell in each hand, palms facing your torso.','Hold your elbows near your torso and your upper arms stationary.','Set the shoulders and upper arms before bending the elbows.','Curl with palms facing each other and elbows near your sides; avoid rocking back.','Keep both shoulders level and resist turning toward the working arm.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('2zNKRUB','Wrist Circles','lower arms','forearms',array['hands','wrists'],'bodyweight',array['Reach your arms straight out in front of you.','Close both hands into fists.','Relax the limb above the joint you are circling.','Circle the joint slowly in one direction, then reverse the circle without forcing the range.','Keep the rest of the limb still while the joint traces each circle.','Switch to the other side after completing both directions.'],0),
('33AzZeV','Barbell Front Raise and Pullover','chest','pectorals',array['deltoids','triceps'],'barbell',array['Stand and set your feet about shoulder width and hold a barbell with palms facing down.','Maintain straight arms and raise the barbell in front of you until it reaches shoulder height.','Set the ribs down and keep a small elbow bend before lowering the weight.','Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.','Keep the ribs down as the arms travel overhead.','Pull the weight back over the chest along the same arc, without lifting the ribs.'],0),
('3d7wHyd','Dumbbell Bench Seated Press','shoulders','deltoids',array['triceps','pectorals'],'dumbbell',array['Take a seat on a bench with a dumbbell in each hand, resting on your thighs.','Recline and position the dumbbells to the sides of your chest, palms facing forward.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('3eGE2JC','Dumbbell Front Raise','shoulders','deltoids',array['biceps','trapezius'],'dumbbell',array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.','With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.','Start with a manageable load and a small bend in the elbows.','Lift the arms forward to about shoulder height, keeping the ribs down and torso still.','Stop near shoulder height rather than shrugging to lift higher.','Lower the arms slowly to your sides without swinging the weight.'],0),
('3omWx6P','Band Alternating Biceps Curl','upper arms','biceps',array['forearms'],'resistance band',array['Stand and set your feet about shoulder width and hold the band with palms facing up.','Hold your elbows near your sides and With control curl one arm up toward your shoulder, squeezing your biceps at the top.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Finish one side''s motion before the other side takes over.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('3s4NnTh','Dumbbell Standing Biceps Curl','upper arms','biceps',array['forearms'],'dumbbell',array['Stand tall with a dumbbell in each hand, palms facing forward and arms straight.','With your upper arms stationary, exhale and curl the weights while contracting your biceps.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('3T12T87','Dumbbell Standing Bent Over Two-Arm Triceps Extension','upper arms','triceps',array['deltoids','back'],'dumbbell',array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.','Bend forward at the waist, with your spine steady and your knees soft.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('3tAXPQ6','Dumbbell Over Bench Reverse Wrist Curl','lower arms','forearms',array['biceps','brachialis'],'dumbbell',array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing down.','Support the forearms on the bench while leaving the wrists free beyond its edge.','Keep the elbows relaxed so the small muscles of the hand or forearm take the load.','Move through the wrists or fingers while the forearms stay supported and still.','Use a small, smooth range without swinging the elbows.','Ease back to the start without letting the load fall from your hands.'],0),
('3TZduzM','Barbell Incline Bench Press','chest','pectorals',array['deltoids','triceps'],'barbell',array['Angle the bench to roughly 45 degrees.','Get onto the bench with your feet planted.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],22),
('3uj0Ozg','Dynamic Chest Stretch','chest','pectorals',array['deltoids','triceps'],'bodyweight',array['Stand tall and set your feet about shoulder width.','Reach your arms straight out to the sides, parallel to the ground.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('3XFdb1Z','Cable Squatting Curl','upper arms','biceps',array['forearms'],'cable',array['Connect a cable handle to the lowest setting on a cable machine.','Face the machine from a stable stance with feet about shoulder width.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('3xK09Sk','Bodyweight Squatting Row','back','upper back',array['biceps','deltoids'],'bodyweight',array['Stand and set your feet about shoulder width, holding onto a sturdy object or suspension trainer with your arms extended.','Lower your body into a squat position, with your spine steady and your knees behind your toes.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('3ZflifB','Cable Pushdown','upper arms','triceps',array['forearms'],'cable',array['Connect a straight bar to a high pulley cable machine.','Face the machine with your feet about shoulder width and a slight bend in your knees.','Stand far enough from the stack for the cable to stay taut.','Keep your elbows near your ribs and straighten your arms against the cable.','Keep the elbows close to the body instead of letting the shoulders swing.','Ease back to the start before repeating.'],41),
('4c9BhzB','Cable Lateral Pulldown with V-Bar','back','latissimus dorsi',array['biceps','forearms'],'cable',array['Sit down on the cable pulldown machine and grab the v-bar attachment with palms facing down.','Set the knee pad so that your thighs are secured under it.','Sit tall and set the shoulders before drawing the handle down.','Pull the handle down by driving your elbows toward your ribs; keep your torso steady.','Pull with the elbows rather than leaning far back to move the handle.','Let the handle rise steadily until the arms are long, then reset the shoulders.'],0),
('4CBIBOM','Barbell Seated Close-Grip Behind Neck Triceps Extension','upper arms','triceps',array['deltoids'],'barbell',array['Take a seat on a bench with your back straight and feet planted.','Take hold of the barbell with a close grip behind your neck, palms facing forward.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('4cWjYEN','Narrow Push-Up on Exercise Ball','upper arms','triceps',array['pectorals','deltoids'],'stability ball',array['Set the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than about shoulder width.','Brace your trunk and keep your body in a straight line from head to toe.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the ball steady and use the feet to manage your balance.','Press back to straight arms, keeping the body line intact.'],0),
('4dF3maG','Dumbbell Single-Arm Hammer Preacher Curl','upper arms','biceps',array['forearms'],'dumbbell',array['Take a seat on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.','Take hold of the dumbbell with a neutral grip (palms facing your body).','Set the working upper arm against the preacher pad and leave the elbow free to bend.','Curl the weight while your upper arms stay in contact with the pad.','Keep both shoulders level and resist turning toward the working arm.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('4dUn2iv','Barbell Standing Close-Grip Curl','upper arms','biceps',array['forearms'],'barbell',array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up, hands close together.','Hold your elbows near your torso and your upper arms stationary throughout the movement.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('4f8RXP8','Cable Standing Row (V-Bar)','back','upper back',array['biceps','deltoids'],'cable',array['Face the cable machine from a stable stance with feet about shoulder width.','Hold the v-bar attachment with palms facing down.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('4GqRrAk','Superman Push-Up','chest','pectorals',array['core','deltoids'],'bodyweight',array['Begin in a high plank position with your hands just beyond shoulder width and your feet together.','Brace your trunk and lower your body toward the ground, keeping your elbows close to your sides.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('4hATdoB','Single-Arm Cable Rope Preacher Curl','upper arms','biceps',array['forearms'],'cable',array['Connect a rope handle to a low pulley cable machine.','Face the machine from a stable stance with feet about shoulder width.','Set the working upper arm against the preacher pad and leave the elbow free to bend.','Curl the weight while your upper arms stay in contact with the pad.','Keep both shoulders level and resist turning toward the working arm.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('4ievMJ9','Dumbbell Seated Bent Over Triceps Extension','upper arms','triceps',array['deltoids','back'],'dumbbell',array['Plant both feet while seated on a bench; hold a dumbbell in each hand.','Bend forward at the waist, with your spine steady and your head up.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('4IKbhHV','Alternate Lateral Pulldown','back','latissimus dorsi',array['biceps','rhomboids'],'cable',array['Take a seat on the cable machine with your back straight and feet planted.','Hold the handles with palms facing down, just beyond shoulder width.','Sit tall and set the shoulders before drawing the handle down.','Pull the handle down by driving your elbows toward your ribs; keep your torso steady.','Finish one side''s motion before the other side takes over.','Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it.'],0),
('4Jc36XM','Dumbbell Over Bench Single-Arm Reverse Wrist Curl','lower arms','forearms',array['biceps','brachialis'],'dumbbell',array['Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing down.','Set your forearm on the bench with your wrist hanging off the edge.','Keep the elbows relaxed so the small muscles of the hand or forearm take the load.','Move through the wrists or fingers while the forearms stay supported and still.','Keep both shoulders level and resist turning toward the working arm.','Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.'],0),
('4Jt8QsQ','Push-Up on Lower Arms','upper arms','triceps',array['pectorals','deltoids'],'bodyweight',array['Begin in a plank position with your forearms on the ground and elbows directly below your shoulders.','Brace your trunk and keep your body in a straight line from head to toe.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('4KJEpzb','Kettlebell Bottoms Up Clean From the Hang Position','upper arms','biceps',array['forearms','deltoids'],'kettlebell',array['Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.','Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.','Brace before the pull and keep the load close to the body.','Drive through the legs and hips, then guide the weight to its receiving position.','Receive the load with the torso braced and feet stable.','Stand tall to finish, then lower the weight under control before the next rep.'],0),
('4Leypho','Barbell Skier','shoulders','deltoids',array['triceps','core'],'barbell',array['Stand and set your feet about shoulder width and hold a barbell ahead of your thighs with palms facing down.','Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.','Brace before the pull and keep the load close to the body.','Drive through the legs and hips, then guide the weight to its receiving position.','Receive the load with the torso braced and feet stable.','Stand tall to finish, then lower the weight under control before the next rep.'],0),
('4LIG9xr','Barbell Reverse Preacher Curl','upper arms','biceps',array['forearms'],'barbell',array['Take a seat on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with palms facing down.','With your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.','Set the working upper arm against the preacher pad and leave the elbow free to bend.','Curl the weight while your upper arms stay in contact with the pad.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('4LoWllp','Band Fixed Back Close-Grip Pulldown','back','latissimus dorsi',array['biceps','forearms'],'resistance band',array['Connect the band to a fixed point above you, such as a pull-up bar or sturdy beam.','Sit down on a bench or chair facing the band, with your feet planted and your knees bent.','Sit tall and set the shoulders before drawing the handle down.','Pull the handle down by driving your elbows toward your ribs; keep your torso steady.','Control the band on the way back instead of letting it snap you into position.','Let the handle rise steadily until the arms are long, then reset the shoulders.'],0),
('4Ml7QFO','Hanging Straight-Leg Raise','waist','abdominals',array['hip flexors'],'bodyweight',array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.','Brace your trunk and lift your legs up in front of you, keeping them straight.','Brace the abdomen and keep the shoulders anchored to the support.','Lift your legs by bracing your trunk and moving at the hips rather than swinging.','Slow the legs before they pull the lower back out of position.','Lower the legs slowly without swinging or losing your trunk position.'],0),
('4OaumBr','Suspended Row','back','upper back',array['biceps','deltoids'],'bodyweight',array['Prepare a suspension trainer at an appropriate height.','Face the anchor point from a stable stance with feet about shoulder width.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('4U7iLb5','Machine Pullover','back','latissimus dorsi',array['triceps','deltoids'],'leverage machine',array['Set the seat and handles of the leverage machine to a comfortable position.','Take a seat on the machine with your back against the pad and Hold the handles with palms facing down.','Set the ribs down and keep a small elbow bend before lowering the weight.','Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.','Keep the ribs down as the arms travel overhead.','Pull the weight back over the chest along the same arc, without lifting the ribs.'],0),
('4x5Okof','Band Seated Chest Press','chest','pectorals',array['deltoids','triceps'],'resistance band',array['Take a seat on a chair or bench with your back straight and feet planted.','Take hold of the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Control the band on the way back instead of letting it snap you into position.','Lower the weight to its starting height under control before pressing again.'],0),
('50BETrz','Biceps Narrow Pull-Ups','upper arms','biceps',array['forearms','deltoids'],'bodyweight',array['Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.','Brace your trunk and pull yourself up toward the bar, focusing on using your biceps to lift your body.','Begin from a controlled hang with the shoulders active rather than slack.','Pull your elbows down and bring your upper chest toward the bar without kicking your legs.','Avoid swinging the legs to clear the bar.','Lower to long arms without dropping suddenly from the top.'],0),
('53Ttlck','Dumbbell Lying Rear Lateral Raise','shoulders','deltoids',array['trapezius','rhomboids'],'dumbbell',array['Position yourself face down on a flat bench with a dumbbell in each hand, palms facing each other.','Extend your arms straight down toward the floor, keeping a slight bend in your elbows.','Start with a manageable load and a small bend in the elbows.','Raise the arms out to the sides to about shoulder height without leaning or shrugging.','Stop near shoulder height rather than shrugging to lift higher.','Lower the arms slowly to your sides without swinging the weight.'],0),
('5bpPTHv','Kettlebell Pistol Squat','upper legs','glutes',array['quadriceps','hamstrings','calves'],'kettlebell',array['Stand and set your feet about shoulder width, holding a kettlebell ahead of your chest with both hands.','Before moving, lift your left foot off the ground and extend it forward, keeping it parallel to the ground.','Brace the abdomen and spread pressure across the whole foot.','Extend the free leg ahead of you as you squat on the standing leg, keeping its heel grounded.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('5BZHW9s','Squat to Overhead Reach with Twist','upper legs','quadriceps',array['glutes','hamstrings','core'],'bodyweight',array['Stand and set your feet about shoulder width and toes slightly turned out.','Before moving, lower your body into a squat position by bending your knees and pushing your hips back.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('5eLRITT','Dumbbell Stiff Leg Deadlift','upper legs','glutes',array['hamstrings','erector spinae'],'dumbbell',array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.','With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting a slight bend in your knees.','Unlock the knees and brace the abdomen before moving the hips back.','Push the hips back while keeping the load close and the spine steady.','Keep the weight close to the legs and stop when the back would begin to round.','Drive the hips forward to stand tall without leaning back at the top.'],0),
('5fKX7wi','Dumbbell Seated Reverse-Grip Single-Arm Overhead Triceps Extension','upper arms','triceps',array['deltoids'],'dumbbell',array['Take a seat on a bench with your back straight and feet planted.','Take a dumbbell with palms facing up and extend your arm straight up overhead.','Set the upper arms in place before extending the elbows.','Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.','Keep both shoulders level and resist turning toward the working arm.','Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.'],0),
('5KLbZWx','Kettlebell Alternating Press','shoulders','deltoids',array['triceps','core'],'kettlebell',array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.','Before moving, press one kettlebell overhead, fully extending your arm.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Finish one side''s motion before the other side takes over.','Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.'],0),
('5MRH8H2','Ski Step','cardio','cardiovascular system',array['quadriceps','hamstrings','glutes','calves'],'bodyweight',array['Stand and set your feet about shoulder width.','Bend your knees slightly and Keep your spine in a comfortable neutral position.','Start at a pace that lets the feet and arms move in sync.','Bound from side to side, landing on one foot as the other leg sweeps behind it.','Keep the pattern repeatable as speed increases.','Keep the rhythm for the planned interval, slowing if your form starts to slip.'],0),
('5uFK1xr','Barbell Seated Overhead Triceps Extension','upper arms','triceps',array['deltoids'],'barbell',array['Take a seat on a bench with your back straight and feet planted.','Take a barbell with palms facing down, hands about shoulder width, and raise it overhead.','Set the upper arms in place before extending the elbows.','Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('5v7KYld','Smith Incline Bench Press','chest','pectorals',array['deltoids','triceps'],'smith machine',array['Set the bench to a 30-45 degree incline.','Take a seat on the bench with your back flat against the pad and feet firmly on the ground.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('5VCj6iH','Barbell Hack Squat','upper legs','glutes',array['quadriceps','hamstrings','calves'],'barbell',array['Begin by standing with your feet about shoulder width and your toes slightly turned out.','Take hold of the barbell behind your legs, resting it on your upper thighs.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('5vfAI0I','Dumbbell Scott Press','shoulders','deltoids',array['triceps','pectorals'],'dumbbell',array['Take a seat on a bench with a dumbbell in each hand, palms facing forward.','Before moving, raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
