('wPypxFY','Cable Side Bend','waist','abdominals',array['obliques'],'cable',array['Stand and set your feet about shoulder width and Hold the cable handle with one hand.','Keep your spine in a comfortable neutral position and your core engaged.','Stand or sit tall with the pelvis facing forward.','Bend sideways through the waist without twisting or letting the hips shift.','Let the side of the trunk work; do not twist or shift the hips.','Bring the weight or body back to its starting position without rushing.'],0),
('wQ2c4XD','Barbell Romanian Deadlift','upper legs','glutes',array['hamstrings','erector spinae'],'barbell',array['Stand and set your feet about shoulder width and your toes pointing forward.','Take hold of the barbell with palms facing down, hands just beyond shoulder width.','Unlock the knees and brace the abdomen before moving the hips back.','Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.','Keep the weight close to the legs and stop when the back would begin to round.','Drive the hips forward to stand tall without leaning back at the top.'],27),
('wqNPGCg','Cable Rear Delt Row (With Rope)','shoulders','deltoids',array['trapezius','rhomboids','biceps'],'cable',array['Connect a rope handle to a low pulley cable machine.','Face the machine from a stable stance with feet about shoulder width.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],19),
('WrYPP2g','Cable Single-Arm Straight Back High Row (Kneeling)','back','upper back',array['biceps','deltoids'],'cable',array['Connect a handle to a cable machine at waist height.','Kneel facing the cable machine and grab the handle with one hand.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Keep both shoulders level and resist turning toward the working arm.','Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.'],0),
('wSScovH','Band Bent-Over Hip Extension','upper legs','glutes',array['hamstrings','erector spinae'],'resistance band',array['Secure the band low on a solid anchor.','Face the away from the anchor point from a stable stance with feet about shoulder width.','Plant the feet and keep the ribs from flaring as the hips prepare to rise.','Press through the feet and lift your hips until your torso and thighs line up.','Control the band on the way back instead of letting it snap you into position.','Lower the hips steadily and keep the feet planted for the next lift.'],0),
('wt6rwjk','Dumbbell Palm Rotational Bent Over Row','back','upper back',array['biceps','forearms'],'dumbbell',array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.','Bend forward at the hips, with your spine steady and your knees soft.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('wu5LXwz','Olympic Barbell Triceps Extension','upper arms','triceps',array['deltoids'],'olympic barbell',array['Begin by standing with your feet about shoulder width and holding the barbell with palms facing down.','Raise the barbell above your head, straighten your arms.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('WU9BLIs','Weighted Russian Twist (Legs Up)','waist','abdominals',array['obliques','hip flexors'],'weighted',array['Take a seat on the ground with your knees bent and feet lifted off the ground, keeping your legs together.','Take hold of the weight with both hands ahead of your chest, keeping your elbows soft.','Set the pelvis and make the turn through the rib cage.','Turn through the torso while the hips and lower body stay as steady as the setup allows.','Keep the turn smooth instead of throwing the arms across the body.','Return through center before turning to the other side.'],0),
