('za9Ni4z','Barbell Rack Pull','upper legs','glutes',array['hamstrings','erector spinae'],'barbell',array['Prepare a barbell on a rack at knee height.','Stand and set your feet about shoulder width, toes pointing slightly outwards.','Unlock the knees and brace the abdomen before moving the hips back.','Push the hips back while keeping the load close and the spine steady.','Keep the weight close to the legs and stop when the back would begin to round.','Drive the hips forward to stand tall without leaning back at the top.'],0),
('zCgxPbV','Cable Twisting Pull','back','latissimus dorsi',array['deltoids','biceps'],'cable',array['Connect a cable handle to a low pulley and stand facing the machine.','Hold the handle with your left hand and step away from the machine, extending your arm fully.','Set the pelvis and make the turn through the rib cage.','Turn through the torso while the hips and lower body stay as steady as the setup allows.','Keep the turn smooth instead of throwing the arms across the body.','Return through center before turning to the other side.'],0),
('zd4P4B2','Stalder Press','upper arms','triceps',array['deltoids','core'],'bodyweight',array['Begin by standing with your feet about shoulder width and your arms extended overhead.','Bend your knees slightly and Brace your trunk.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('Ze7MoIb','Dumbbell Single-Arm Reverse-Grip Press','chest','pectorals',array['triceps','deltoids'],'dumbbell',array['Take a seat on a flat bench with a dumbbell in one hand, palm facing toward your body.','Set your feet planted and Keep your spine in a comfortable neutral position.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep both shoulders level and resist turning toward the working arm.','Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.'],0),
('ZEkjZDi','Kettlebell Seated Two-Arm Military Press','shoulders','deltoids',array['triceps','upper back'],'kettlebell',array['Take a seat on a bench with your back straight and feet planted.','Take a kettlebell in each hand at shoulder level with your palms facing forward.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('zfNHMN9','Skater Hops','cardio','cardiovascular system',array['quadriceps','hamstrings','glutes','calves'],'bodyweight',array['Stand and set your feet about shoulder width.','Before moving, bend your knees slightly and jump to the right, landing on your right foot.','Bend the hips and knees slightly to load the jump.','Load the legs with a small bend, then drive through the floor and land softly.','Land with bent hips and knees and let the feet absorb the impact.','Absorb the landing through the hips and knees before repeating.'],0),
('ZfyAGhK','Cable Standing Rear Delt Row (With Rope)','shoulders','deltoids',array['trapezius','rhomboids','biceps'],'cable',array['Face the cable machine from a stable stance with feet about shoulder width.','Take hold of the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('zFzbBfL','Band Push Sit-Up','waist','abdominals',array['deltoids','pectorals'],'resistance band',array['Connect the band securely to a stable anchor point.','Settle onto your back with your knees bent and feet planted.','Set the pelvis and keep the neck relaxed before curling upward.','Curl your rib cage toward your pelvis, letting the abdominals move the torso.','Control the band on the way back instead of letting it snap you into position.','Lower the shoulders or torso with control before the next curl.'],0),
('zG0zs85','Barbell Front Squat','upper legs','glutes',array['quadriceps','hamstrings','calves','core'],'barbell',array['Begin by standing with your feet about shoulder width, toes slightly turned out.','Take hold of the barbell ahead of your shoulders, resting it on your collarbone and shoulders.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],17),
('Zg3XY7P','Machine Seated Leg Curl','upper legs','hamstrings',array['calves'],'leverage machine',array['Set the machine to fit your body and sit on it with your back against the backrest.','Set your lower legs under the padded lever, just above your ankles.','Line the knees up with the machine or bench edge before starting the curl.','Bend your knees to draw the pad toward you without lifting your hips from the support.','Keep the hips still while the knees bend.','Return along the same path at a controlled pace.'],0),
('ZgwWBoC','Cable Thibaudeau Kayak Row','back','latissimus dorsi',array['biceps','rhomboids','rear deltoids'],'cable',array['Connect a cable handle to a low pulley and sit facing the machine with your feet planted.','Hold the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('ZH68exZ','Band Fixed Back Underhand Pulldown','back','latissimus dorsi',array['biceps','rhomboids','rear deltoids'],'resistance band',array['Connect the band to a sturdy anchor point above your head.','Face the anchor point from a stable stance with feet about shoulder width.','Sit tall and set the shoulders before drawing the handle down.','Pull the handle down by driving your elbows toward your ribs; keep your torso steady.','Control the band on the way back instead of letting it snap you into position.','Let the handle rise steadily until the arms are long, then reset the shoulders.'],0),
('zHEpuuc','Cable Assisted Inverse Leg Curl','upper legs','hamstrings',array['glutes','calves'],'cable',array['Set the cable machine so that the ankle attachment is at the lowest setting.','Position yourself face down on the bench with your legs straight and the ankle attachment secured to your ankles.','Line the knees up with the machine or bench edge before starting the curl.','Bend your knees to draw the pad toward you without lifting your hips from the support.','Keep the hips still while the knees bend.','Return along the same path at a controlled pace.'],0),
('zhF9lW4','Band Assisted Wheel Rollout','waist','abdominals',array['erector spinae'],'resistance band',array['Get down on the floor and hold the handles of the band with both hands, palms facing down.','Set the band on the ground in front of you and position your hands about shoulder width.','Tighten the abdomen and keep the pelvis tucked before the arms reach away.','Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.','Control the band on the way back instead of letting it snap you into position.','Pull back to the start through your shoulders and abdominals, keeping the same body line.'],0),
('zhMwOwE','Hyperextension','back','erector spinae',array['glutes','hamstrings'],'bodyweight',array['Set the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.','Fold your arms over your chest or place your hands behind your head.','Secure the hips and feet on the support before lifting.','Raise your torso or legs until they line up with your body, without arching sharply at the lower back.','Finish in a straight body line, before the lower back overarches.','Bring the weight or body back to its starting position without rushing.'],0),
('ziFKQXP','Dumbbell Single-Arm French Press on Exercise Ball','upper arms','triceps',array['deltoids'],'dumbbell',array['Take a seat on an exercise ball with your feet planted and your back straight.','Take a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.','Set the upper arms in place before extending the elbows.','Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.','Keep both shoulders level and resist turning toward the working arm.','Straighten the elbows to bring the bar overhead, then begin the next controlled rep; switch sides when the set calls for it.'],0),
('zILLZ98','Smith Machine Biceps Curl','upper arms','biceps',array['forearms'],'smith machine',array['Set the height of the smith machine bar to be at waist level.','Face the smith machine from a stable stance with feet about shoulder width.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Keep the torso quiet and let the elbow bend lift the weight.','Lower until the elbows are nearly straight, keeping the upper arms still.'],0),
('ZIViNh1','Dumbbell Reverse-Grip Incline Bench Single-Arm Row','back','upper back',array['biceps','deltoids'],'dumbbell',array['Angle the bench to roughly 45 degrees.','Set a dumbbell on the floor next to the bench.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Keep both shoulders level and resist turning toward the working arm.','Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.'],0),
('zK8Fu1W','Smith Reverse-Grip Press','chest','pectorals',array['triceps','deltoids'],'smith machine',array['Set the height of the smith machine bar to chest level.','Face the bar from a stable stance with feet about shoulder width.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the palms in the chosen grip without bending the wrists back.','Lower the weight to its starting height under control before pressing again.'],0),
('zkgRrbK','Hyperextension (On Bench)','back','erector spinae',array['glutes','hamstrings'],'bodyweight',array['Set the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.','Fold your arms over your chest or place your hands behind your head.','Secure the hips and feet on the support before lifting.','Raise your torso or legs until they line up with your body, without arching sharply at the lower back.','Finish in a straight body line, before the lower back overarches.','Ease back to the start before repeating.'],0),
('ZNgOYQU','Vertical Leg Raise (On Parallel Bars)','waist','abdominals',array['hip flexors'],'bodyweight',array['Suspend yourself from the parallel bars with your arms straight and your body straight.','Brace your trunk and lift your legs up in front of you, keeping them straight.','Brace the abdomen and keep the shoulders anchored to the support.','Lift your legs by bracing your trunk and moving at the hips rather than swinging.','Slow the legs before they pull the lower back out of position.','Lower the legs slowly without swinging or losing your trunk position.'],0),
('ZnJHhMk','Machine Seated Crunch (Chest Pad)','waist','abdominals',array['obliques'],'leverage machine',array['Set the seat height and chest pad position according to your comfort.','Take a seat on the machine with your back against the chest pad and your feet planted.','Set the pelvis and keep the neck relaxed before curling upward.','Curl your rib cage toward your pelvis, letting the abdominals move the torso.','Leave a little space between the chin and chest; keep the movement in the torso.','Lower the shoulders or torso with control before the next curl.'],0),
('znLogoF','Barbell Pullover to Press','back','latissimus dorsi',array['triceps','pectorals','deltoids'],'barbell',array['Settle onto a bench with your head at one end and your feet on the ground.','Take hold of the barbell with a pronated grip (palms turned away from you) and extend your arms straight above your chest.','Set the ribs down and keep a small elbow bend before lowering the weight.','Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.','Keep the ribs down as the arms travel overhead.','Pull the weight back over the chest along the same arc, without lifting the ribs.'],0),
('znP9SIh','Hug Knees to Chest','upper legs','glutes',array['hamstrings','quadriceps'],'bodyweight',array['Begin by standing with your feet about shoulder width.','Before moving, bend your knees and lower your body down into a squat position.','Settle into the starting position and take an easy breath before moving deeper.','Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.','Stay in a mild stretch rather than pulling farther with momentum.','Hold the position with steady breathing, then release gently; repeat on the other side if needed.'],0),
('znQUdHY','Dumbbell Seated Shoulder Press','shoulders','deltoids',array['triceps','upper back'],'dumbbell',array['Take a seat on a bench with a dumbbell in each hand, resting on your thighs.','Before moving, raise the dumbbells to shoulder height, palms facing forward.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],42),
('zoOvPcx','Smith Wide-Grip Bench Press','chest','pectorals',array['triceps','deltoids'],'smith machine',array['Set the bench to a comfortable position on the smith machine.','Get onto the bench with your feet planted.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('ZOuKWir','Kneeling Push-Up','chest','pectorals',array['triceps','deltoids'],'bodyweight',array['Begin by kneeling on the ground with your hands about shoulder width, fingers pointing forward.','Reach your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.','Brace the abdomen and glutes so the shoulders, hips and ankles move together.','Bend your elbows to lower your chest while keeping your body in one line.','Keep the head in line with the spine as the elbows bend.','Press back to straight arms, keeping the body line intact.'],0),
('ZqNOWQ6','Machine Reverse-Grip Vertical Row','back','upper back',array['biceps','forearms'],'leverage machine',array['Set the seat height and footplate position to ensure proper alignment.','Take a seat on the machine with your chest against the pad and your feet flat on the footplate.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Keep the palms in the chosen grip without bending the wrists back.','Reach the arms forward again without letting the torso lurch.'],0),
('ZsiqXYa','Barbell JM Bench Press','upper arms','triceps',array['pectorals','deltoids'],'barbell',array['Settle onto a bench with your feet planted and your back pressed against the bench.','Hold the barbell with palms facing down, just beyond shoulder width.','Brace the torso and align the wrists with the forearms.','Press the weight or handles away while keeping your trunk braced.','Keep the wrists stacked and use a shoulder path that feels natural.','Lower the weight to its starting height under control before pressing again.'],0),
('ZSJNetl','Cable High Row (Kneeling)','back','upper back',array['biceps','deltoids'],'cable',array['Fit a straight bar to the pulley at chest level.','Kneel in front of the cable machine and grab the bar with palms facing down, hands about shoulder width.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('ZSY3MsL','Self Assisted Inverse Leg Curl (On Floor)','upper legs','hamstrings',array['glutes','calves'],'bodyweight',array['Settle onto your back with your legs extended and your arms by your sides.','Bend your knees and place your feet planted, about hip width.','Line the knees up with the machine or bench edge before starting the curl.','Bend your knees to draw the pad toward you without lifting your hips from the support.','Keep the hips still while the knees bend.','Ease back to the start before repeating.'],0),
('ztAa1RK','Band Alternating V-Up','waist','abdominals',array['hip flexors'],'resistance band',array['Settle onto your back with your legs straight and your arms extended overhead, holding the band.','Tighten your midsection and lift your legs and upper body off the ground simultaneously, reaching your hands toward your toes.','Set the pelvis and keep the neck relaxed before curling upward.','Raise your straight legs and torso together, reaching toward the feet before lowering under control.','Finish one side''s motion before the other side takes over.','Lower the shoulders or torso with control before the next curl; switch sides when the set calls for it.'],0),
('ZujAdR9','Cable Rope Incline Triceps Extension','upper arms','triceps',array['deltoids'],'cable',array['Connect a rope to a high pulley and adjust the incline bench to a comfortable angle.','Face the away from the pulley from a stable stance with feet about shoulder width.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep the upper arms steady while the forearms travel.','Bend the elbows slowly to return to the start of the next rep.'],0),
('ZuPXtCK','Smith Hack Squat','upper legs','glutes',array['quadriceps','hamstrings','calves'],'smith machine',array['Set the barbell on the smith machine to an appropriate height for your body.','Stand and set your feet about shoulder width, toes slightly pointed outwards.','Brace the abdomen and spread pressure across the whole foot.','Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.','Drive upward with the chest and hips rising together; keep the knees from collapsing inward.','Stand fully, reset your footing and breathing, then begin the next descent.'],0),
('ZuXu4Eq','V-Sit on Floor','waist','abdominals',array['hip flexors'],'bodyweight',array['Take a seat on the floor with your legs extended in front of you.','Recline slightly and lift your legs off the ground, keeping them straight.','Brace the abdomen and find a position you can maintain without holding your breath.','Brace your midsection and hold the position while breathing normally.','Keep breathing steadily as you maintain the same body line.','Keep the shape for the planned time, then come out of it with control.'],0),
('Zwiw7XR','Dumbbell Alternating Biceps Curl with Leg Raised on Exercise Ball','upper arms','biceps',array['forearms','deltoids'],'dumbbell',array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.','Set an exercise ball behind you and position one foot on top of it, keeping your balance.','Set the shoulders and upper arms before bending the elbows.','Bend your elbows to bring the weight toward your shoulders without swinging your torso.','Finish one side''s motion before the other side takes over.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('ZX9UZmj','Smith Bent Over Row','back','upper back',array['biceps','forearms'],'smith machine',array['Prepare the smith machine with the bar at hip height.','Face the bar from a stable stance with feet about shoulder width.','Set the torso and allow the arms to reach forward without rounding excessively.','Draw your elbows back and bring the handle or weight toward your torso.','Bring the elbows back without jerking the torso.','Reach the arms forward again without letting the torso lurch.'],0),
('ZXnjcOQ','Cable Single-Arm Reverse Preacher Curl','upper arms','biceps',array['forearms'],'cable',array['Move the cable pulley to its lowest setting.','Face the cable machine from a stable stance with feet about shoulder width.','Set the working upper arm against the preacher pad and leave the elbow free to bend.','Curl the weight while your upper arms stay in contact with the pad.','Keep both shoulders level and resist turning toward the working arm.','Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.'],0),
('zYmNaoY','Elevator','back','upper back',array['deltoids','trapezius'],'bodyweight',array['Stand and set your feet about shoulder width and your knees soft.','Set your hands on your hips or cross them ahead of your chest.','Unlock the knees and brace the abdomen before moving the hips back.','Push the hips back while keeping the load close and the spine steady.','Keep the weight close to the legs and stop when the back would begin to round.','Drive the hips forward to stand tall without leaning back at the top.'],0),
('ZZKbeMw','Machine Shrug','back','trapezius',array['deltoids'],'leverage machine',array['Fit the seat to your body, then settle into the machine.','Hold the handles with palms facing down and keep your arms straight.','Let the arms hang long and keep the head neutral.','Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.','Lift and lower vertically without circling the shoulders.','Ease back to the start before repeating.'],0),
('zZlORz6','Dumbbell Lying Single-Arm Supinated Triceps Extension','upper arms','triceps',array['forearms'],'dumbbell',array['Settle onto a bench with your back and head supported, and your feet planted.','Take a dumbbell in one hand with palms facing up, and extend your arm straight up above your shoulder.','Set the upper arms in place before extending the elbows.','Keep the upper arms steady and extend through the elbows to move the weight.','Keep both shoulders level and resist turning toward the working arm.','Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.'],0),
('ZZTGMKh','Single-Arm Against Wall','back','latissimus dorsi',array['deltoids','triceps'],'bodyweight',array['Face the wall from a stable stance with feet about shoulder width.','Reach one arm straight out in front of you and place your palm against the wall.','Brace the abdomen and find a position you can maintain without holding your breath.','Brace your midsection and hold the position while breathing normally.','Keep both shoulders level and resist turning toward the working arm.','Keep the shape for the planned time, then come out of it with control; switch sides when the set calls for it.'],0)
